def paragraphs(text):
    return [p.strip() for p in text.strip().split("\n\n") if p.strip()]


def cover_bytes():
    path = APP_DIR / "frontend" / "public" / "assets" / "cover-fallback.png"
    return path.read_bytes() if path.is_file() else None


def make_fb2(title, author, annotation, chapters, cover):
    info = f'<author><nickname>{html.escape(author)}</nickname></author><book-title>{html.escape(title)}</book-title><annotation><p>{html.escape(annotation)}</p></annotation><lang>ru</lang><sequence name="Демонстрационная библиотека"/>'
    if cover:
        info += '<coverpage><image l:href="#cover"/></coverpage>'
    body = "".join(f'<section id="s{i}"><title><p>{html.escape(label)}</p></title>' + "".join(f'<p>{html.escape(p)}</p>' for p in paragraphs(text)) + '</section>' for i, (label, text) in enumerate(chapters))
    binary = '<binary id="cover" content-type="image/png">' + base64.b64encode(cover).decode() + '</binary>' if cover else ""
    return ('<?xml version="1.0" encoding="utf-8"?><FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0" xmlns:l="http://www.w3.org/1999/xlink"><description><title-info>' + info + '</title-info></description><body>' + body + '</body>' + binary + '</FictionBook>').encode()


def zip_write(z, name, data):
    # Fixed timestamp makes retrying an interrupted seed produce the same book hash.
    info = zipfile.ZipInfo(name, date_time=(2026, 1, 1, 0, 0, 0))
    info.compress_type = zipfile.ZIP_DEFLATED
    z.writestr(info, data)


def transparent_illustration():
    """Small procedural PNG test fixture with genuine transparent/alpha pixels."""
    width, height = 720, 320
    rows = bytearray()
    for y in range(height):
        rows.append(0)
        for x in range(width):
            first = ((x - 265) / 175) ** 2 + ((y - 155) / 110) ** 2 < 1
            second = ((x - 450) / 155) ** 2 + ((y - 155) / 110) ** 2 < 1
            if first and second:
                pixel = (70, 115, 130, 215)
            elif first:
                pixel = (61, 110, 86, 160)
            elif second:
                pixel = (67, 105, 161, 160)
            elif 73 < y < 246 and (x in range(55, 58) or x in range(663, 666)):
                pixel = (120, 120, 120, 200)
            else:
                pixel = (0, 0, 0, 0)
            rows.extend(pixel)
    def chunk(kind, content):
        return struct.pack(">I", len(content)) + kind + content + struct.pack(">I", zlib.crc32(kind + content) & 0xFFFFFFFF)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(bytes(rows), 9)) + chunk(b"IEND", b"")


def make_epub(path, cover):
    with zipfile.ZipFile(path, "w") as z:
        z.writestr(zipfile.ZipInfo("mimetype", date_time=(2026, 1, 1, 0, 0, 0)), "application/epub+zip")
        zip_write(z, "META-INF/container.xml", '<?xml version="1.0"?><container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>')
        items = '<item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/><item id="illustration" href="illustration.png" media-type="image/png"/>'
        spine = ""
        nav = ""
        for i, (label, text) in enumerate(LAYOUT):
            items += f'<item id="s{i}" href="chapter{i}.xhtml" media-type="application/xhtml+xml"/>'
            spine += f'<itemref idref="s{i}"/>'
            nav += f'<navPoint id="s{i}" playOrder="{i+1}"><navLabel><text>{html.escape(label)}</text></navLabel><content src="chapter{i}.xhtml"/></navPoint>'
            pieces = [f'<p>{html.escape(p)}</p>' for p in paragraphs(text)]
            if i == 0:
                pieces.insert(1, '<p><em>Курсив</em> и <strong>полужирное начертание</strong> сохраняются внутри книги.</p>')
            if i == 1:
                pieces.insert(1, '<figure><img src="illustration.png" alt="Два полупрозрачных круга на прозрачном фоне"/><figcaption>Демонстрационная иллюстрация: прозрачность на белой подложке.</figcaption></figure>')
            if i == 2:
                pieces.insert(2, '<p>Перейти к <a href="notes.xhtml#n1">демонстрационному примечанию</a>.</p>')
            doc = f'<?xml version="1.0" encoding="utf-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>{html.escape(label)}</title></head><body><h1>{html.escape(label)}</h1>' + "".join(pieces) + '</body></html>'
            zip_write(z, f"OPS/chapter{i}.xhtml", doc)
        items += '<item id="notes" href="notes.xhtml" media-type="application/xhtml+xml"/>'
        spine += '<itemref idref="notes"/>'
        if cover:
            items += '<item id="cover-image" href="cover.png" media-type="image/png" properties="cover-image"/>'
            zip_write(z, "OPS/cover.png", cover)
        meta = '<dc:identifier id="bookid">urn:pereplet:demo:layout:1</dc:identifier><dc:title>Страница, свет и воздух</dc:title><dc:creator>Демо · Переплёт</dc:creator><dc:language>ru</dc:language><dc:description>Оригинальный демонстрационный EPUB: набор, прозрачная иллюстрация и внутренние ссылки.</dc:description>'
        if cover:
            meta += '<meta name="cover" content="cover-image"/>'
        zip_write(z, "OPS/content.opf", '<?xml version="1.0" encoding="utf-8"?><package version="3.0" unique-identifier="bookid" xmlns="http://www.idpf.org/2007/opf" xmlns:dc="http://purl.org/dc/elements/1.1/"><metadata>' + meta + '</metadata><manifest>' + items + '</manifest><spine toc="ncx">' + spine + '</spine></package>')
        zip_write(z, "OPS/toc.ncx", '<?xml version="1.0" encoding="utf-8"?><ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1"><head/><docTitle><text>Страница, свет и воздух</text></docTitle><navMap>' + nav + '</navMap></ncx>')
        zip_write(z, "OPS/notes.xhtml", '<?xml version="1.0" encoding="utf-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>Примечание</title></head><body><h1>Примечание</h1><p id="n1">Это демонстрационное примечание. Ссылка открыла другой раздел EPUB. Можно вернуться к предыдущему месту кнопкой возврата в читалке или через оглавление.</p><p>Никакого скрытого секрета здесь нет — только проверка удобного перехода по книге.</p></body></html>')
        zip_write(z, "OPS/illustration.png", transparent_illustration())


def mark_demo_covers():
    """Add presentation metadata only, once, for still-present seeded book IDs."""
    marker = library.DATA_DIR / "demo-seeded-v1.json"
    if not marker.is_file():
        return {"updated": 0, "reason": "not_seeded"}
    state = json.loads(marker.read_text(encoding="utf-8"))
    if state.get("cover_template_version") == 1:
        return {"updated": 0, "reason": "already_marked"}
    updated = 0
    with library.connect() as db:
        for book_id in state.get("book_ids", []):
            row = db.execute("SELECT metadata FROM books WHERE id=?", (book_id,)).fetchone()
            if row is None:
                continue
            meta = json.loads(row["metadata"])
            if not meta.get("cover_resource") or meta.get("cover_kind") == "template":
                continue
            meta["cover_kind"] = "template"
            db.execute("UPDATE books SET metadata=? WHERE id=?", (json.dumps(meta, ensure_ascii=False), book_id))
            updated += 1
    state["cover_template_version"] = 1
    marker.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"updated": updated}


def seed():
    library.init()
    seed_catalogs()
    marker = library.DATA_DIR / "demo-seeded-v1.json"
    if marker.is_file():
        mark_demo_covers()
        return {"seeded": False, "reason": "already_initialized"}
    imported = []
    if not library.list_books():
        with tempfile.TemporaryDirectory(prefix="demo-", dir=library.DATA_DIR / "tmp") as tmp:
            root = Path(tmp)
            cover = cover_bytes()
            first = root / "pereplet-guide.fb2"
            first.write_bytes(make_fb2("Переплёт: первые страницы", "Руководство · Переплёт", "Оригинальное руководство первой версии. Добавление книг, настройки чтения, библиотека, OPDS и озвучка.", GUIDE, cover))
            second = root / "quiet-shore.fb2.zip"
            with zipfile.ZipFile(second, "w") as z:
                zip_write(z, "quiet-shore.fb2", make_fb2("Тихий берег", "Демо · Переплёт", "Оригинальный демонстрационный рассказ о книгах, маяке и тихом рабочем дне. Написан специально для проверки чтения.", STORY, cover))
            third = root / "page-light-air.epub"
            make_epub(third, cover)
            for path in (first, second, third):
                imported.append(library.import_path(path)["book"]["id"])
    marker.write_text(json.dumps({"version": 1, "created_at": library.now(), "book_ids": imported}, ensure_ascii=False, indent=2), encoding="utf-8")
    mark_demo_covers()
    return {"seeded": True, "books": imported}


if __name__ == "__main__":
    print(json.dumps(seed(), ensure_ascii=False))
